import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Muhtasari wa Cosmos ya Heng Yuan Zhou","description":"","frontmatter":{},"headers":[],"relativePath":"sw/00-衡元宙宇宙总览.md","filePath":"sw/00-衡元宙宇宙总览.md","lastUpdated":null}'),o={name:"sw/00-衡元宙宇宙总览.md"};function e(w,a,s,h,k,m){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="muhtasari-wa-cosmos-ya-heng-yuan-zhou" tabindex="-1">Muhtasari wa Cosmos ya Heng Yuan Zhou <a class="header-anchor" href="#muhtasari-wa-cosmos-ya-heng-yuan-zhou" aria-label="Permalink to &quot;Muhtasari wa Cosmos ya Heng Yuan Zhou&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>00</td></tr><tr><td>Moduli</td><td>Kanuni za Jumla na Mipangilio ya Msingi</td></tr><tr><td>Maneno Muhimu</td><td>Heng Yuan Zhou, Kitu cha Nanga, Usawa, Kabila Kumi na Elfu, Asili</td></tr></tbody></table><h2 id="_1-ufafanuzi-wa-msingi-wa-cosmos" tabindex="-1">1. Ufafanuzi wa Msingi wa Cosmos <a class="header-anchor" href="#_1-ufafanuzi-wa-msingi-wa-cosmos" aria-label="Permalink to &quot;1. Ufafanuzi wa Msingi wa Cosmos&quot;">​</a></h2><p>Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa, kwa kifupi &quot;Heng Yuan Zhou&quot;, ni eneo zima la ulimwengu ambalo Ustaarabu wa Usawa wa Nanga unaishi na kutawala. Heng Yuan Zhou sio nafasi moja ya kimwili, bali ni kiumbe cha muundo kinachoundwa pamoja na Njia ya Nyenzo, Tabaka la Nishati, Kanda ya Fahamu, na Mtandao wa Sheria. Katika jina lake, &quot;Roho Kumi na Elfu&quot; inarejelea kila aina ya uhai wenye uwezo wa fahamu na mageuzi; &quot;Nanga Iliyosawazishwa&quot; inarejelea utaratibu wa Kitu cha Nanga kinachobakilisha usawa wa ulimwengu; na &quot;Cosmos Asili&quot; inasisitiza asili ya msingi ya ulimwengu huu, ambao inajengwa kwenye sheria za asili na inaelekeza katika mageuzi ya usawa.</p><p>Sifa kuu ya Heng Yuan Zhou iko katika &quot;uwezo wake wa kutoa mageuzi&quot;. Tofauti na mtazamo wa ulimwengu wa uwindaji wa jadi ambao huchukulia ulimwengu kama uwanja wa uwindaji wa rasilimali mdogo, Heng Yuan Zhou inaamini kuwa ulimwengu yenyewe ni kiumbe hai, na mchakato wake wa kuongezeka kwa entropy unaweza kubadilishwa na kudhibitiwa kupitia mtandao wa usawa ulio pangwa. Utaratibu wa Kitu cha Nanga ndio hasa njia kuu ya udhibiti huu — kwa kuanzisha vitu vya nanga vilivyo thabiti katika vigezo vya muhimu vya ulimwengu, nishati ya kibinafsi iliyotawanyikwa inaunganywa kuwa mkondo wa mageuzi ulio pangwa, na hatimaye kufikia Kupanda Mwelekeo (kuinua mwelekeo) wa ulimwengu mzima.</p><h2 id="_2-muundo-wa-tabaka-za-cosmos" tabindex="-1">2. Muundo wa Tabaka za Cosmos <a class="header-anchor" href="#_2-muundo-wa-tabaka-za-cosmos" aria-label="Permalink to &quot;2. Muundo wa Tabaka za Cosmos&quot;">​</a></h2><p>Heng Yuan Zhou imegawanywa katika tabaka nne za kimuundo, ambazo hazijatanganyiki, bali zinahusiana kupitia mtandao wa vitu vya nanga:</p><table tabindex="0"><thead><tr><th>Tabaka</th><th>Jina</th><th>Sifa</th><th>Wakazi wa Kuu</th></tr></thead><tbody><tr><td>Tabaka ya Kwanza</td><td>Njia ya Nyenzo</td><td>Dunia ya kimwili inayofuata sheria za fizikia, ikiwa na nyota na galaksi zaidi ya hesabu</td><td>Kabila la Binadamu na maisha mengi ya kimwili</td></tr><tr><td>Tabaka ya Pili</td><td>Tabaka la Nishati</td><td>Maeneo ya makusanyo ya nishati ya kiwango cha juu, sheria zinaonekana nusu-zaheri</td><td>Maisha ya nishati, miili ya roho ya waozaji</td></tr><tr><td>Tabaka ya Tatu</td><td>Kanda ya Fahamu</td><td>Nafasi ya taarifa ambapo fahamu ya jumla na ya kibinafsi zinakutana</td><td>Vitu vya Fahamu, viumbe vya mwelekeo wa juu</td></tr><tr><td>Tabaka ya Nne</td><td>Mtandao wa Sheria</td><td>Tabaka ya msingi ya utendaji wa sheria za asili za ulimwengu, tabaka ya mizi ya Kitu cha Nanga</td><td>Kitu cha Nanga chenyewe, Dhamira ya Ulimwengu</td></tr></tbody></table><p>Mtiririko wa nishati na taarifa wa tabaka nze unafuata kanuni ya &quot;kuingia chini, kukusanya juu&quot;: matokeo ya uozi wa tabaka za chini yanakusanya juu hadi Mtandao wa Sheria, na mwisho wa thabiti wa Mtandao wa Sherai unashuka chini kulea maisha ya kila tabaka. Kitu cha Nanga, kama kitovu cha muunganisho cha kati ya tabaka, kinahakikisha kuwa mtiririko huu hautakatiwi na tabia za uwindaji.</p><h2 id="_3-uginginishaji-wa-msingi-wa-cosmos" tabindex="-1">3. Uginginishaji wa Msingi wa Cosmos <a class="header-anchor" href="#_3-uginginishaji-wa-msingi-wa-cosmos" aria-label="Permalink to &quot;3. Uginginishaji wa Msingi wa Cosmos&quot;">​</a></h2><p>Uginginishaji wa msingi wa Heng Yuan Zhou ni uginginishaji kati ya &quot;uwindaji na usawa&quot;. Kabla ya utaratibu wa Kitu cha Nanga kuanzishwa kikamilifu, mfumo wa uozi wa uwindaji ulikuwa umetawala kwa muda mrefu utaratibu wa ulimwengu — wenye nguvu walikuwa wanageuza kwa kumeza nishati, bahati, na hata asili ya wanyonge, na kusababisha kuongezeka kwa entropy ya ulimwengu mzima na kukatika kwa ustaarabu mara kwa mara. Mfumo huu unaweza kuzalisha wale waliouweza kwa muda mfupi, lakini kwa muda mrefu unakomesha uwezo wa mageuzi wa ulimwengu.</p><p>Kuzaliwa kwa Ustaarabu wa Usawa wa Nanga ni hasa jibu kwa uginginishaji huu. Kwa kufungua Mifumo Mia Tatu ya Uozi wa Asili ya Ulimwengu, kuanzisha Mfumo wa Mkataba unaohusishwa na Uzalishaji, na kuwasha 20% ya viumbe kuwa Mwenye Nguvu Mkuu wa Njia, ustaarabu wa usawa unajaribu kuthibitisha kuwa mageuzi hayahitaji kafara ya wengine, na mageuzi ya jumla yaliyo pangwa yana bora zaidi kuliko kuruka kwa uwindaji wa kibinafsi.</p><h2 id="_4-mwelekeo-wa-maendeleo-ya-cosmos" tabindex="-1">4. Mwelekeo wa Maendeleo ya Cosmos <a class="header-anchor" href="#_4-mwelekeo-wa-maendeleo-ya-cosmos" aria-label="Permalink to &quot;4. Mwelekeo wa Maendeleo ya Cosmos&quot;">​</a></h2><p>Mwelekeo wa mwisho wa Heng Yuan Zhou ni &quot;usawa wa Kabila Kumi na Elfu, kupanda mwelekeo wa ulimwengu&quot;. Mwelekeo huu unafikiwa kwa hatua nne:</p><ol><li><strong>Kujenga Msingi katika Ukweli</strong>: kuanzisha mifumo ya kijamii ya usawa katika Njia ya Nyenzo, kuondoa mizizi ya uwindaji</li><li><strong>Kutoa Uwezo wa Teknolojia</strong>: kuunganisha sheria za uozi na uhandisi wa teknolojia, kupunguza kizuizi cha mageuzi</li><li><strong>Mageuzi ya Fahamu</strong>: kukuza uhamishaji wa maisha kwenda Kanda ya Fahamu, kutimiza usawa katika kiwango cha kiroho</li><li><strong>Usawa wa Kati ya Nyota</strong>: kujenga mtandao kamili wa vitu vya nanga kati ya njia na kati ya nyota, kukamilisha kupanda mwelekeo wa ulimwengu mzima</li></ol><p>Kwa sasa, Heng Yuan Zhou iko katika kipindi muhimu cha mpito kutoka hatua ya kwanza hadi hatua ya pili, na mifumo mbalimbali ya Ustaarabu wa Usawa wa Nanga inatekelezwa kikamilifu.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Heng Yuan Zhou sio ulimwengu tulivu, bali ni jumuiya ya maisha inayotoa mageuzi. Kuelewa Heng Yuan Zhou ni kuelewa uwezekano wa mageuzi ya usawa. Muhtasari huu unatumika kama kwanza cha hati zote; moduli zinazofuata zitaeleza kwa undani kutoka vipengele vya sheria, utaratibu, jamii, sheria, maisha, teknolojia, historia, na kati ya njia.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Tangazo la Ustaarabu wa Usawa wa Nanga)</li><li>03-共生文明宪章 (Katiba ya Ustaarabu wa Usawa)</li><li>10-三百套本源修炼体系总览 (Muhtasari wa Mifumo Mia Tatu ya Uozi wa Asili)</li></ul>',20)])])}const r=i(o,[["render",e]]);export{d as __pageData,r as default};
